import React from 'react';
import hero from './images/Hero Banner.jpg'
import NavigationBar from './components/NavigationBar';
// import './App.css';

function App() {
  return (
    <div className="App">
      <header className="App-header">
        <NavigationBar />
      </header>
        <img style={{ width: 500, height: 500}} src={hero} alt="hero banner of the QuackBox"></img>

    </div>
  );
}

export default App;
